<?php
namespace App\Services;
use App\Models\{Order,Payment}; use Illuminate\Support\Facades\Http; use RuntimeException;
class ZarinpalService { private function base():string{return config('services.zarinpal.sandbox')?'https://sandbox.zarinpal.com/pg/v4':'https://api.zarinpal.com/pg/v4';} public function request(Order $order):Payment{$payment=Payment::create(['order_id'=>$order->id,'gateway'=>'zarinpal','amount'=>$order->total,'status'=>'pending']);$res=Http::acceptJson()->post($this->base().'/payment/request.json',['merchant_id'=>config('services.zarinpal.merchant_id'),'amount'=>$order->total,'description'=>'خرید بلیت سینماپلاس '.$order->code,'callback_url'=>config('services.zarinpal.callback_url'),'metadata'=>['mobile'=>'']]);$data=$res->json();$code=$data['data']['code']??null;if($code!==100)throw new RuntimeException('خطا در ایجاد درخواست پرداخت زرین‌پال: '.($data['errors']['message']??$code));$payment->update(['authority'=>$data['data']['authority'],'response'=>$data]);return $payment;} public function url(Payment $payment):string{return ($this->base()==='https://sandbox.zarinpal.com/pg/v4'?'https://sandbox.zarinpal.com/pg/StartPay/':'https://www.zarinpal.com/pg/StartPay/').$payment->authority;} public function verify(Payment $payment):bool{$order=$payment->order;$res=Http::acceptJson()->post($this->base().'/payment/verify.json',['merchant_id'=>config('services.zarinpal.merchant_id'),'amount'=>$payment->amount,'authority'=>$payment->authority]);$data=$res->json();$code=$data['data']['code']??null;if(in_array($code,[100,101],true)){$payment->update(['status'=>'paid','response'=>$data]);return true;}$payment->update(['status'=>'failed','response'=>$data]);return false;} }
class ZarinpalService { private function base():string{return config('services.zarinpal.sandbox')?'https://sandbox.zarinpal.com/pg/v4':'https://api.zarinpal.com/pg/v4';} public function request(Order $order):Payment{$payment=Payment::create(['order_id'=>$order->id,'gateway'=>'zarinpal','amount'=>$order->total,'status'=>'pending']);$res=Http::acceptJson()->post($this->base().'/payment/request.json',['merchant_id'=>config('services.zarinpal.merchant_id'),'amount'=>$order->total,'description'=>'خرید بلیت سینماپلاس '.$order->code,'callback_url'=>config('services.zarinpal.callback_url'),'metadata'=>['mobile'=>'']]);$data=$res->json();$code=$data['data']['code']??null;if($code!==100)throw new RuntimeException('خطا در ایجاد درخواست پرداخت زرین‌پال: '.($data['errors']['message']??$code));$payment->update(['authority'=>$data['data']['authority'],'response'=>$data]);return $payment;} public function url(Payment $payment):string{return ($this->base()==='https://sandbox.zarinpal.com/pg/v4'?'https://sandbox.zarinpal.com/pg/StartPay/':'https://www.zarinpal.com/pg/StartPay/').$payment->authority;} public function verify(Payment $payment):bool{$res=Http::acceptJson()->post($this->base().'/payment/verify.json',['merchant_id'=>config('services.zarinpal.merchant_id'),'amount'=>$payment->amount,'authority'=>$payment->authority]);$data=$res->json();$code=$data['data']['code']??null;if(in_array($code,[100,101],true)){$payment->update(['status'=>'paid','response'=>$data]);return true;}$payment->update(['status'=>'failed','response'=>$data]);return false;} public function refund(Payment $payment):bool{$res=Http::acceptJson()->post($this->base().'/payment/reverse.json',['merchant_id'=>config('services.zarinpal.merchant_id'),'authority'=>$payment->authority]);$data=$res->json();$ok=in_array($data['data']['code']??null,[100,101],true);$payment->update(['status'=>$ok?'refunded':'refund_failed','response'=>$data]);return $ok;} }
